import pandas as pd

def clean(df):
    df = df.copy()
    island_map = {'Torgerson': 'Torgersen', 'Bisco': 'Biscoe'}
    df['island'] = df['island'].replace(island_map)
    return df

def answer(df):
    adelie = df[df['species'] == 'Adelie'].dropna(subset=['island'])
    return adelie.groupby('island')['bill_length_mm'].mean().round(2).to_dict()
